  NPC_CHUNKS.aiko={words:[["after the set","演出结束后"],["one more song","再听一首"],["quiet walk","安静地走走"],["clear my ears","让耳朵歇歇"],["small venue","小场地"]],starter:[["After the set, I walk home slowly.","演出结束后，我会慢慢走回家。"],["One more song, then a quiet break.","再听一首歌，然后安静歇一会儿。"],["I like a small venue.","我喜欢小小的演出场地。"]],everyday:[["After a live show, I walk a few quiet streets before taking the train.","看完现场演出后，我会安静地走几条街，再去坐车。"],["I help put on small shows, so I make sure to leave some quiet time afterwards.","我会办小型演出，所以结束后会给自己留一点安静时间。"],["A familiar song helps me switch off for the night.","听一首熟悉的歌，能让我慢慢结束这一天。"]],fluent:[["I spend so much time listening closely at work that I need a little silence on the way home.","工作时我总要认真听声音，所以回家的路上我需要一点安静。"],["After the last band packs up, I walk home without putting on another track.","最后一支乐队收好设备后，我会不放音乐，慢慢走回家。"],["I used to think every free minute needed a soundtrack; now I enjoy a little quiet too.","以前我觉得每一分钟都该有音乐陪着；现在我也开始享受安静了。"]],after:{starter:[["That sounds nice.","听起来不错。"],["Pick one for me.","替我选一首吧。"],["A quiet walk sounds good.","安静地走走也不错。"]],everyday:[["I like a small show too.","我也喜欢小型演出。"],["Let’s leave the next song for later.","下一首歌留到一会儿再听吧。"],["A little quiet can feel good.","安静一会儿也挺舒服。"]],fluent:[["A good song can stay with you even after it ends.","一首好歌结束以后，还会在心里留一会儿。"],["I like how a quiet walk lets the evening settle.","我喜欢安静地走一走，让夜晚慢慢沉下来。"],["You’ve made room for both music and rest.","你给音乐和休息都留了位置。"]]}};
  NPC_CHUNKS.jiwoo={words:[["after work","下班后"],["short walk","走一小段"],["warm tea","热茶"],["quiet room","安静的房间"],["early night","早点休息"]],starter:[["After work, I rest.","下班后，我休息一下。"],["I like warm tea.","我喜欢热茶。"],["A short walk helps.","走一小段会舒服些。"]],everyday:[["After work, I make tea and sit quietly.","下班后，我会泡茶，安静地坐一会儿。"],["A short walk helps me feel less tired.","走一小段路会让我没那么累。"],["I try to put my phone away before bed.","睡觉前我尽量把手机收起来。"]],fluent:[["After testing software all day, I need a little time when nothing needs fixing.","测了一整天软件以后，我想有一会儿什么都不用修。"],["A short walk home helps me leave work thoughts at work.","走一小段路回家，能让我把工作的事先留在工作里。"],["I’m learning that rest works better when I don’t wait until I’m exhausted.","我正在学着早点休息，而不是等到筋疲力尽才停下来。"]],after:{starter:[["Me too.","我也是。"],["Tea sounds nice.","喝茶不错。"],["Let’s take a short walk.","我们走一小段吧。"]],everyday:[["I do that after work too.","我下班后也会这样。"],["A warm drink sounds good.","来杯热饮不错。"],["Let’s leave the phones for a bit.","我们先把手机放一会儿吧。"]],fluent:[["It can be hard to switch off after a busy day.","忙了一天以后，确实不容易马上放松下来。"],["A small pause still counts as rest.","短短停一下，也是在休息。"],["I hope you find a rhythm that feels kind to you.","希望你能找到一种让自己舒服的节奏。"]]}};
  NPC_CHUNKS.lena={words:[["tea break","喝茶休息"],["fresh air","新鲜空气"],["slow morning","慢慢的早晨"],["garden path","花园小路"],["clear my mind","理清思绪"]],starter:[["I take a tea break.","我会喝茶休息一下。"],["Fresh air helps me.","呼吸点新鲜空气会舒服些。"],["I like a slow morning.","我喜欢慢慢开始早晨。"]],everyday:[["I take my tea outside when the weather is good.","天气好的时候，我会把茶带到外面喝。"],["A short walk helps me clear my mind.","短短走一会儿，能帮我理清思绪。"],["I leave a little space between work and home.","我会在工作和回家之间给自己留一点空档。"]],fluent:[["I study how attention works, but I still need to step away from my own screen.","我研究注意力如何运作，但我自己也需要离开屏幕休息一下。"],["A quiet walk gives my thoughts time to settle without trying to solve them.","安静地走一走，让思绪慢慢沉下来，不必急着解决什么。"],["I’m trying to treat rest as part of a healthy rhythm, not a prize for finishing everything.","我在练习把休息当作生活节奏的一部分，而不是做完所有事后的奖励。"]],after:{starter:[["That sounds lovely.","听起来不错。"],["Let’s get some fresh air.","我们出去透透气吧。"],["A slow morning is nice.","慢慢开始一天挺好的。"]],everyday:[["I like taking tea outside too.","我也喜欢把茶带到外面喝。"],["A short walk sounds perfect.","走一小会儿正合适。"],["Let’s leave a little space today.","今天也给自己留一点空档吧。"]],fluent:[["Knowing about rest and making room for it are different skills.","知道休息重要，和真的给休息留出时间，是两回事。"],["It’s kind to yourself to stop before you run empty.","在精力耗尽前停下来，是在善待自己。"],["I hope your day has a little breathing room.","希望你今天能有一点喘息的空间。"]]}};
  NPC_CHUNKS.priyashah={words:[["train ride","火车车程"],["book group","读书会"],["after work","下班后"],["one story","一个故事"],["slow evening","轻松的晚上"]],starter:[["I take the train home.","我坐火车回家。"],["I like this story.","我喜欢这个故事。"],["After work, I rest.","下班后，我休息一下。"]],everyday:[["I choose a short story for our book group.","我给读书会挑一个短故事。"],["The train is busy, so I listen to music.","火车上人很多，所以我会听音乐。"],["On Sunday, I cook with my cousin.","星期天我和表姐一起做饭。"]],fluent:[["After work, a good story helps me leave the busy day behind.","下班后，读一个好故事能让我暂时放下忙碌的一天。"],["I like our book group because everyone brings a different point of view.","我喜欢读书会，因为每个人都会带来不同的看法。"],["The ride home is crowded, but I use that time to listen and unwind.","回家的火车很挤，但我会利用这段时间听听东西、放松一下。"]],after:{starter:[["Me too.","我也是。"],["Which story?","哪个故事？"],["Rest sounds good.","休息一下不错。"]],everyday:[["I’d like to join the book group.","我也想参加读书会。"],["Music makes the ride easier.","听音乐会让车程轻松些。"],["What are you cooking?","你们做什么吃？"]],fluent:[["A shared story can bring people together.","一起读同一个故事，能让人们更亲近。"],["I like that you make time for your cousin.","我喜欢你会留时间陪表姐。"],["I hope the ride home feels a little lighter today.","希望你今天回家的路上能轻松一点。"]]}};
  NPC_CHUNKS.giulia={words:[["bike ride","骑车"],["book proofs","校样"],["coffee break","咖啡休息"],["rest break","休息一下"],["good story","好故事"]],starter:[["I ride my bike.","我骑自行车。"],["I read at a café.","我在咖啡馆看书。"],["A coffee break helps.","喝咖啡歇一下会舒服些。"]],everyday:[["I read book proofs over coffee.","我一边喝咖啡，一边看书的校样。"],["After work, I ride home slowly.","下班后，我会慢慢骑车回家。"],["On Sundays, I cook pasta with friends.","星期天我和朋友一起做意面。"]],fluent:[["Editing all day makes me appreciate an evening with no deadline.","编辑了一整天以后，我会格外珍惜没有截止时间的晚上。"],["I like reading a few pages at a café before cycling home.","我喜欢在咖啡馆读几页书，再骑车回家。"],["A story can take you somewhere new without asking you to leave your own chair.","读一个故事，就能去新的地方看看，不必离开自己的椅子。"]],after:{starter:[["That sounds nice.","听起来不错。"],["Save me a page.","给我留一页吧。"],["Let’s take a coffee break.","我们喝杯咖啡歇一下吧。"]],everyday:[["I like reading in cafés too.","我也喜欢在咖啡馆看书。"],["A slow ride sounds good.","慢慢骑一会儿不错。"],["What kind of pasta?","你做哪种意面？"]],fluent:[["A quiet evening can be creative too.","安静的晚上也可以很有创造力。"],["You’ve made a lovely little ritual for yourself.","你给自己安排了一个很舒服的小习惯。"],["I hope you get to enjoy the story, not just edit it.","希望你也能享受故事，而不只是编辑它。"]]}};

