  function activityAudioUrl(text,id,learn){const H=window.LIFE_ACTIVITY_VOICE_HAS;if(learn!=="zh"||!H)return"";const key=activityVoiceKey(text,id);if(!H.has(key))return"";if(location.protocol==="file:"){const inSource=/\/地图源文件\/(?:page|template2)\.html$/.test(decodeURIComponent(location.pathname));return new URL((inSource?"voice_out/":"地图源文件/voice_out/")+key+".mp3",location.href).href;}return"https://img.heyvoyo.com/voice/"+key+".mp3";}
