    const audioUrl=activityAudioUrl(text,id,learn);if(audioUrl){try{speechSynthesis.cancel();if(window.HV_LIFE_ACTIVITY_AUDIO){window.HV_LIFE_ACTIVITY_AUDIO.pause();}const audio=window.HV_LIFE_ACTIVITY_AUDIO=new Audio(audioUrl);audio.playbackRate=Number(person?.age)>=60?.9:1;audio.onerror=fallback;const played=audio.play();if(played?.catch)played.catch(fallback);return;}catch{}}
    fallback();
