function TG(a, o){ if (!a) return ""; o = o || {}; const zh = LG() === "zh", t = a[0], py = zh ? a[1] : "", m = zh ? TR(a[2] || "") : (ZH() ? a[1] : ""), rev = o.voice ? ` data-lbvoice="${esc(o.voice)}"` : "";
  return `<span data-nopy><span class="lb-tg" data-say="${esc(t)}"${rev}>${esc(t)}<i>🔊</i></span>${py && !o.nopy ? `<span class="lb-py">${esc(py)}</span>` : ""}${m && !o.nom ? `<span class="lb-mean">${esc(m)}</span>` : ""}</span>`; }
const LVS = () => [["a2", T("刚开始", "Starting")], ["b1", T("能聊日常", "Everyday")], ["b2", T("比较流利", "Fluent")]];
// 故事按标点切成可跟上的语义段；中文拼音只有在段数一致时才逐段配对。
function storyParts(text, lang){
  const raw=String(text||"").trim(); if(!raw)return [];
  if(lang==="zh") return (raw.match(/[^，；。！？]+[，；。！？]?/g)||[raw]).map(x=>x.trim()).filter(Boolean);
  const protectedText=raw.replace(/\b(?:Mr|Mrs|Ms|Dr|Prof|St|Jr|Sr|vs|etc)\./gi,m=>m.slice(0,-1)+"\uE000").replace(/\b(?:e\.g|i\.e)\./gi,m=>m.replace(/\./g,"\uE000")).replace(/(\d)\.(\d)/g,"$1\uE000$2");
  const sentences=(protectedText.match(/[^.!?]+[.!?]+["'”’»」』）)\]]*(?:\s+|$)|[^.!?]+$/g)||[protectedText]).map(x=>x.replace(/\uE000/g,".")), out=[];
  const pushPart=value=>{let rest=value.trim();while(rest.length>58){const re=/\s+(?=(?:while|when|because|although|if|as|but|and|so|with|I)\b)/gi;let m,cut=-1;while((m=re.exec(rest))&&m.index<=58&&rest.length-m.index>=20)cut=m.index;if(cut<0)break;out.push(rest.slice(0,cut).trim());rest=rest.slice(cut).trim();}if(rest)out.push(rest);};
  sentences.forEach(sentence=>{
    const clauses=sentence.match(/[^,;]+[,;]?/g)||[sentence];let carry="";
    clauses.forEach((part,i)=>{
      part=part.trim();if(!part)return;
      if(carry&&carry.length+1+part.length>58){pushPart(carry);carry="";}
      carry+=(carry?" ":"")+part;
      if(/;$/.test(part)||/[.!?]["'”’»」』）)\]]?$/.test(part)||!/[;,]$/.test(part)||carry.length>=58||i===clauses.length-1){pushPart(carry);carry="";}
    });
    if(carry)pushPart(carry);
  });
  return out.filter(part=>/[A-Za-z0-9\u3400-\u9fff]/.test(part));
}
function storySpeechH(intro, zh){
  const lang=zh?"zh":"en", text=zh?intro[0]:intro[2], py=zh?String(intro[1]||""):"", parts=storyParts(text,lang);
  const pyParts=py?(py.match(/[^,;.!?]+[,;.!?]?/g)||[py]).map(x=>x.trim()).filter(Boolean):[];
  const aligned=zh&&pyParts.length===parts.length;
  const chunks=parts.map((part,i)=>`${aligned?`<span class="lb-story-chunk"><small class="lb-story-chunk-py">${esc(pyParts[i])}</small>`:""}<span class="lb-story-segment" data-say="${esc(part)}" data-lg="${TTS()}" data-lbvoice="npc-v2" data-lb-pause="${/[，,；;]$/.test(part)?430:620}">${esc(part)}</span>${aligned?"</span>":""}`).join(" ");
  return `<p class="lb-story-line" data-lb-story role="button" tabindex="0" aria-label="${T("播放分段故事","Play story in short segments")}">${chunks} <i>🔊</i></p>${zh?`${aligned?"":`<small class="lb-story-py">${esc(py)}</small>`}<small class="lb-story-mean">${esc(intro[2]||"")}</small>`:`<small class="lb-story-mean">${esc(intro[0]||"")}</small>`}`;
}

