let pg = null, V = "poster", DAY = 0, DAY_PANEL = "task", TASK_STAGE = 0, VOCAB_RUN = 0, CIRCLE_PANEL = "people", PEOPLE_KIND = "npc", CIRCLE_REVEAL = 0, FEED_INDEX = 0, OPEN = {}, FOUND = {}, QUIZ_ON = {}, QUIZ_TRY = {}, HINT = {}, LTAB = null, CTAB = "cola", SAID = {}, CUR = {}, FEED = null, ME2N = {}, NPC_SOCIAL = {likes:{}, mine:{}, comments:{}}, NPC_INDEX = 0, NPC_STEP = 0, NPC_CHUNK = 0, MY_STEP = 0, SENDING_DAY = false;
function mount(){ if (!document.getElementById("lbCss")){ const s = document.createElement("style"); s.id = "lbCss"; s.textContent = CSS; document.head.appendChild(s); }
  if (!pg){ pg = document.createElement("div"); pg.id = "lbPg"; pg.hidden = true; document.body.appendChild(pg); pg.onclick = onClick; pg.addEventListener("toggle",e=>{if(e.target.matches(".lb-optional-practice")&&e.target.open)speakCardSequence(e.target.querySelectorAll("[data-say]"),TTS());},true); pg.addEventListener("keydown",e=>{if(e.target.matches("[data-lb-story],[data-lb-question]")&&(e.key==="Enter"||e.key===" ")){e.preventDefault();if(e.target.matches("[data-lb-story]"))replayStory(e.target);else replayQuestion(e.target);}}); } }
function open(v){ const d = DATA(); if (!d) return; mount(); V = v || (ST().d0 ? "circle" : "poster"); if (V === "circle"){ CIRCLE_PANEL = "people"; PEOPLE_KIND = "npc"; CIRCLE_REVEAL = 0; } pg.hidden = false; document.body.classList.add("lb-on"); draw(); if (V === "circle") autoSpeak(".lb-host-question [data-say]"); loadFeed().then(() => { if (!pg.hidden && (V === "circle" || V === "poster")) redraw(); }); try { window.hvPulse && window.hvPulse("act"); } catch(e){} }
function close(){ if (pg){ pg.hidden = true; } if (!mp || mp.hidden) document.body.classList.remove("lb-on"); try { speechSynthesis.cancel(); } catch(e){} if (AU) AU.pause(); if (/^#(lback|lbackmap)$/.test(location.hash)) history.replaceState(null, "", location.pathname + location.search); }
function autoSpeak(selector){ setTimeout(() => { if ((V !== "day" && !(V === "circle" && ((CIRCLE_PANEL === "people" && PEOPLE_KIND === "npc") || CIRCLE_PANEL === "today"))) || !pg || pg.hidden) return; const s = pg.querySelector(selector); if (!s) return; if(s.matches(".lb-question-segment")){const line=s.closest(".lb-question-line");speakCardSequence(line.querySelectorAll(".lb-question-segment"),s.dataset.lg||TTS());}else speakElement(s); }, 180); }
function autoPlayVocab(){ const run=++VOCAB_RUN; setTimeout(() => { if (V!=="day" || DAY_PANEL!=="task" || TASK_STAGE!==2 || !pg || pg.hidden || run!==VOCAB_RUN) return; speakCardSequence(pg.querySelectorAll(".lb-vocab-row button"),TTS()); },180); }
function go(v){ V = v; if (v === "day"){ TASK_STAGE = 0; VOCAB_RUN++; OPEN[DAY] = false; FOUND[DAY] = []; QUIZ_ON[DAY] = false; QUIZ_TRY[DAY] = null; SAID[DAY] = ""; NPC_INDEX = 0; NPC_STEP = 0; NPC_CHUNK = 0; MY_STEP = 0; DAY_PANEL = "task"; } if (v === "circle"){ CIRCLE_PANEL = "people"; PEOPLE_KIND = "npc"; CIRCLE_REVEAL = 0; NPC_INDEX = 0; NPC_STEP = 0; NPC_CHUNK = 0; } draw(); pg.scrollTop = 0; if (v === "day") { if (DAY_PANEL === "task") autoSpeak(".lb-question [data-say]"); else autoSpeakNpcPack(); } if (v === "circle") autoSpeak(".lb-host-question [data-say]"); }
function redraw(){ const y = pg.scrollTop, panel = pg.querySelector(".lb-circle-content"), py = panel ? panel.scrollTop : null; draw(); pg.scrollTop = y; const next = pg.querySelector(".lb-circle-content"); if (next && py != null) next.scrollTop = py; }
function scrollDayTo(selector){ const pane = pg && pg.querySelector(".lb-day-content"), el = pane && pane.querySelector(selector); if (!pane || !el) return; const y = el.getBoundingClientRect().top - pane.getBoundingClientRect().top + pane.scrollTop - 8; pane.scrollTo({top: y, behavior: "smooth"}); }
function toast(t){ let e = pg.querySelector(".lb-toast"); if (!e){ e = document.createElement("div"); e.className = "lb-toast"; e.setAttribute("data-nopy", ""); pg.appendChild(e); } e.innerHTML = t; e.classList.add("on"); clearTimeout(toast.h); toast.h = setTimeout(() => e.classList.remove("on"), 2200); }
function stamp(h, el){ el = el || pg; const s = document.createElement("div"); s.className = "lb-stamp"; s.setAttribute("data-nopy", ""); s.innerHTML = h; el.appendChild(s); setTimeout(() => s.remove(), 1700); }
function confetti(el){ el = el || pg; const cs = ["#e2552f", "#ffd27a", "#2f7d70", "#14305c", "#3fa34d", "#f2a72b"]; for (let k = 0; k < 36; k++){ const c = document.createElement("i"); c.className = "lb-cf"; c.style.left = Math.random() * 100 + "%"; c.style.background = cs[k % cs.length]; c.style.animationDelay = Math.random() * .4 + "s"; c.style.borderRadius = k % 3 ? "2px" : "50%"; el.appendChild(c); setTimeout(() => c.remove(), 2300); } }
