function snapH(s){ return `<div class="lb-snap" data-nopy><div class="pk">${esc(s.pk)}</div>${s.rows.map((r, i) => `<i class="${s.hl === i ? "hl" : ""}"><span>${esc(r[0])}</span><span>${r[2] === "H" ? `<span class="lt">${esc(r[1])}</span>` : esc(r[1])}</span></i>`).join("")}${s.lupa ? `<span class="lupa">🔍 ${esc(s.lupa)}</span>` : ""}</div>`; }
const who2 = v => v.own ? T("你", "You") : v.nm || (v.l === "zh" ? T("一位在学中文的人", "Someone learning Chinese") : T("一位在学英语的人", "Someone learning English"));
