function npcSocialH(who){ const key=npcSocialKey(who), o=ST(), localLiked=!!(o.npcLikes&&o.npcLikes[key]), liked=!!NPC_SOCIAL.mine[key]||localLiked, likes=(NPC_SOCIAL.likes[key]||0)+(localLiked&&!NPC_SOCIAL.mine[key]?1:0), comments=[...(NPC_SOCIAL.comments[key]||[]),...((o.npcComments&&o.npcComments[key])||[])]; return `<div class="lb-npc-social"><button data-lbnpc-like="${esc(key)}" class="${liked?"on":""}" aria-pressed="${liked}">♥ ${T("喜欢","Like")}${likes?` · ${likes}`:""}</button><details><summary>💬 ${T("评论","Comments")}${comments.length?` · ${comments.length}`:""}</summary><div class="lb-npc-comments">${comments.map(x=>`<p><b>${esc(x.nm||T("一位学习者","A learner"))}</b> ${esc(x.text)}</p>`).join("")||`<small>${T("还没有评论","No comments yet")}</small>`}<textarea data-lbnpc-input="${esc(key)}" maxlength="240" placeholder="${T("写一句友善的评论…","Write a kind comment…")}"></textarea><button data-lbnpc-comment="${esc(key)}">${T("发送","Post")}</button></div></details></div>`; }
// 一条：真人（照片或每天那句）/ 你自己还在手机上的 / 🎭 角色（画的标签截图）
