  const ownAtEnd = CIRCLE_REVEAL >= circleRevealEnd() ? `<section class="lb-topic-own"><h3>${BI("轮到你：拿手边的零食来看看","Your turn: explore a snack you have")}</h3><div class="lb-own-prompt" style="margin:7px 0;padding:9px 10px;border-left:3px solid #6e8b77;border-radius:9px;background:#fff"><b style="display:block;color:#4c6c59;font-size:11px">${BI("Nadia 的问题","NADIA'S QUESTION")}</b>${TG(d.pack_q[lg],{voice:"host-v2"})}</div>${yoursPanel}<button class="lb-continue lb-next-discovery" data-lbcircle-next-topic data-say="${esc(nextQuestion)}" data-lg="${TTS()}" data-lbvoice="host-v2">${BI("看下一组","Next topic")}　🔊</button></section>` : "";
