let AUTO_SEQ = null;
function speakCardSequence(nodes, lang){ const items=[...nodes].filter(x=>x&&x.dataset&&x.dataset.say); if(!items.length)return; const seq={items,index:0,current:-1,play:null}; AUTO_SEQ=seq; seq.play=()=>{ if(AUTO_SEQ!==seq||seq.index>=items.length||!pg||pg.hidden){if(AUTO_SEQ===seq)AUTO_SEQ=null;return;} seq.current=seq.index; const el=items[seq.index++], pause=Number(el.dataset.lbPause)||0; speakElement(el,el.dataset.say,el.dataset.lg||lang||TTS(),el.dataset.lbvoice,()=>{if(AUTO_SEQ===seq)setTimeout(seq.play,pause);},el.dataset.lbAudioOnly==="1"); }; seq.play(); }
function replayAndResume(el,text,lang,voice){ const seq=AUTO_SEQ; if(seq){const i=seq.items.indexOf(el);if(i>seq.current)seq.index=i+1;else if(i>=0&&i<seq.current)seq.index=seq.current;} speakElement(el,text,lang,voice,()=>{if(seq&&AUTO_SEQ===seq)setTimeout(seq.play,Number(el.dataset.lbPause)||0);},el.dataset.lbAudioOnly==="1"); }
function replayQuestion(line){const segments=[...line.querySelectorAll(".lb-question-segment")];if(segments.length)speakCardSequence(segments,segments[0].dataset.lg||TTS());}
function replayStory(story){ const segments=[...story.querySelectorAll(".lb-story-segment")]; if(!segments.length)return; const seq=AUTO_SEQ, first=segments[0], i=seq?seq.items.indexOf(first):-1; if(seq&&i>=0){seq.index=i+1;seq.current=i;speakElement(first,first.dataset.say,first.dataset.lg,first.dataset.lbvoice,()=>{if(AUTO_SEQ===seq)setTimeout(seq.play,Number(first.dataset.lbPause)||0);});}else speakCardSequence(segments,TTS()); }
function speakNpcPack(card){ if(!card)return; speakCardSequence(card.querySelectorAll(".lb-food-say,.lb-story-line .lb-story-segment,.lb-ingredient-rows button"),TTS()); }
function autoSpeakNpcPack(){ setTimeout(()=>{if(!pg||pg.hidden)return;const card=pg.querySelector(".lb-circle-npc-card:last-of-type")||pg.querySelector(".lb-npc-story-card");speakNpcPack(card);},120); }
function autoSpeakPersonal(){ setTimeout(()=>{if(!pg||pg.hidden)return;speakCardSequence(pg.querySelectorAll(".lb-personal [data-say]"),TTS());},120); }
function speakElement(el,text,lang,voice,onend,audioOnly=false){ if(!el)return; if(el.matches(".lb-story-segment")){const pane=el.closest(".lb-circle-content")||pg,r=el.getBoundingClientRect(),pr=pane.getBoundingClientRect(),pad=12;let top=pane.scrollTop;if(r.top<pr.top+pad)top+=r.top-pr.top-pad;else if(r.bottom>pr.bottom-pad)top+=r.bottom-pr.bottom+pad;if(top!==pane.scrollTop)pane.scrollTo({top:Math.max(0,top),behavior:"smooth"});} const cue=el.matches(".lb-food-say")?(el.closest(".lb-food-row")&&el.closest(".lb-food-row").querySelector(".lb-snack-name")):el; if(cue)cue.classList.add("lb-speaking"); say(text||el.dataset.say||"",lang||el.dataset.lg||TTS(),voice||el.dataset.lbvoice,()=>{if(cue&&cue.isConnected)cue.classList.remove("lb-speaking");if(onend)onend();},audioOnly); }
function labelRowSpeech(el){
  const labEl=el.closest("[data-lab]"), lab=labEl&&labEl.dataset.lab, D=DATA(), lg=LG();
  if(!lab||!D)return el.dataset.own||"";
  if(el.dataset.ix!=null){const x=(D.labels[lab]&&D.labels[lab].t||[])[+el.dataset.ix];return x?(lg==="en"?x[0]:x[1]):el.dataset.own||"";}
  return el.dataset.own||"";
}
function labelRowLanguage(el){if(el.dataset.ix!=null)return TTS();const labEl=el.closest("[data-lab]"),lab=labEl&&labEl.dataset.lab,ll=lab?labLang(lab):LG();return ll==="ja"?"ja-JP":ll==="en"?"en-GB":"zh-CN";}
function speakLabelSequence(nodes,lang){
  const items=[...nodes].filter(el=>labelRowSpeech(el));
  items.forEach(el=>{el.dataset.say=labelRowSpeech(el);el.dataset.lg=labelRowLanguage(el)||lang||TTS();el.dataset.lbAudioOnly="1";});
  speakCardSequence(items,lang);
}
async function npcLike(key){ const o=ST(); o.npcLikes=o.npcLikes||{}; const id=NPC_SOCIAL.mine[key]; if(id){ try{if(db())await db().doc(COLL+"/"+id).delete();}catch(_){} delete NPC_SOCIAL.mine[key]; NPC_SOCIAL.likes[key]=Math.max(0,(NPC_SOCIAL.likes[key]||1)-1); } else if(o.npcLikes[key]){ delete o.npcLikes[key]; } else if(logged()&&db()){ try{const ref=db().collection(COLL).doc();await ref.set({author:uid(),act:COLL,kind:"npc-like",to:key,ts:Date.now()});NPC_SOCIAL.mine[key]=ref.id;NPC_SOCIAL.likes[key]=(NPC_SOCIAL.likes[key]||0)+1;}catch(_){o.npcLikes[key]=1;} } else o.npcLikes[key]=1; SAVE(o); redraw(); }
